Nat.minSqFacAux.eq_1 :
  ∀ (x x_1 : ℕ),
    x.minSqFacAux x_1 =
      if h : x < x_1 * x_1 then none
      else
        let_fun this := ⋯;
        if x_1 ∣ x then
          let n' := x / x_1;
          let_fun this := ⋯;
          if x_1 ∣ n' then some x_1 else n'.minSqFacAux (x_1 + 2)
        else x.minSqFacAux (x_1 + 2)
